  {
    "Name": "CommonCacheResources",
    "Key": "ContentManagement",
    "ResourceKey": "ContentManagement",
    "Script": "CommonCacheResources = {
    init: async function(app, container) {
        app = app || session.app;
        container = container || $(".component[name=CommonCacheResources]");
