    newScript: async function (e, cacheGrid) {
        e.preventDefault();
        var newScriptDialog = new Dialog({ width: 520, height: "auto", title: "[resource_displayname[newscript]]" });
        newScriptDialog.template = $("[name=newScriptDialog]").html();

        newScriptDialog.events.create = async function () {
            var script = {
                Name: $("[name=name]", newScriptDialog.element).val(),
                Key: $("[name=key]", newScriptDialog.element).val(),
                Content: "",
                CreatedOn: (new Date()).toISOString(),
                LastUpdated: (new Date()).toISOString()
            };

            var commonObject = {
                Id: 0,
                Key: script.Key,
                Name: script.Name,
                CreatedOn: script.CreatedOn,
                LastUpdated: script.LastUpdated,
                Json: JSON.stringify(script),
                Type: "ContentManagement/Script",
                Culture: "",
                Version: 1
            };

            await api.add("ContentManagement/CommonObject", commonObject)
                .then(async () => {
                    notification.success("[resource_displayname[added]]");
                    await api.get("RefreshCache");
                    notification.success("[resource_displayname[rebuilt]]");
                    cacheGrid.refresh();
                })
                .catch((err) => error(err));

            newScriptDialog.events.close();
        };

        newScriptDialog.init();
    },

    removeFromCache: async function (e, grid) {
        var item = grid.kendoObject.dataItem($(e.currentTarget).closest("tr"));
        await api.destroy("ContentManagement/CommonObject(" + item.Id + ")")
            .then(async () => {
                notification.success("[resource_displayname[deleted]]");
                await api.get("RefreshCache");
                notification.success("[resource_displayname[rebuilt]]");
                grid.refresh();
            })
            .catch((err) => error(err));
    },

    viewVersions: async function (e, grid) {
        var item = grid.dataItem($(e.currentTarget).closest("tr"));
        var versionDialog = new Dialog({ title: "[resource_displayname[viewhistory]]", height: 800, width: 1200 });
        versionDialog.init(() => CommonCacheScripts.versionDialogInit(versionDialog, item));
    },

    versionDialogInit: async function (dialog, item) {
        let dataSource = (await api.get(
            "ContentManagement/CommonObject?$filter=Type eq 'ContentManagement/Script' and Name eq '" + item.Name + "'&$orderby=Version desc"
        )).value;

        var grid = new GridWidget(dialog.element, { data: dataSource, pageSize: 20 });
        grid.columns = [
            { field: "Version", title: "[resource_displayname[version]]" },
            { field: "LastUpdated", title: "[resource_displayname[lastupdated]]", width: 120, type: "date", format: "{0:g}" },
            { field: "LastUpdatedBy", title: "[resource_displayname[lastupdatedby]]", width: 200 }
        ];

        grid.groupable = false;
        grid.detailTemplate = `<div style='height:600px; padding-bottom: 40px;'>
            <div name='scriptEditor'><h4>[resource_displayname[recentscriptchanges]]</h4></div>
        </div>`;

        grid.detailExpand = function (e) {
            var versionedScript = JSON.parse(item.Json);
            var originalScript = JSON.parse(grid.dataItem(e.masterRow).Json);
            var expandContainer = $(e.detailRow);

            var originalScriptModel = monaco.editor.createModel(originalScript.Content, "text/javascript");
            var modifiedScriptModel = monaco.editor.createModel(versionedScript.Content, "text/javascript");

            var diffEditorScript = monaco.editor.createDiffEditor(
                $("[name=scriptEditor]", expandContainer)[0],
                { automaticLayout: true }
            );

            diffEditorScript.setModel({ original: originalScriptModel, modified: modifiedScriptModel });

            monaco.editor.createDiffNavigator(diffEditorScript, { followsCaret: true, ignoreCharChanges: true });
        };


        await grid.init();
    }
};
