  {
    "Name": "SSORoleManagement",
    "Key": "Security",
    "ResourceKey": "Security",
    "Script": "SSORoleManagement = {
	init: async function (app, container, tenant) {
		app = app || session.app;
		container = container || $(".component[name=SSORoleManagement]");

		api.addToMetaCache([
			{
				"Name": "Security",
				"Types": [
					[meta[Security/SSORole]]
				]
			}
		]);

		if (!tenant || !tenant.Id) { throw new Error("A tenant is required to manage roles."); }
		SSORoleManagement.setupRoleGrid(app, container, tenant);
	},

	setupRoleGrid: async function (app, container, tenant) {
		var config = {
			endpoint: "Security/SSORole",
		odataAppend: "?$filter=TenantId eq '" + tenant.Id.replaceAll("'", "''") + "'",
			sort: {
				field: "Name",
				dir: "asc"
			}
		};
		var ds = await model.getDatasource(config);
		var roleGrid = new GridWidget(container, ds);
		roleGrid.groupable = false;
		roleGrid.pageable = false;
		roleGrid.toolbar = [
			{
				template: `<div class='btn-group btn-group-sm'>
					<button class='btn btn-primary' name='createRole'>
						<span class='k-icon k-i-plus'></span>[resource_displayname[NewRole]]
					</button>
				</div>`
			}
		];
		roleGrid.columns = [{
			field: "Name",
			title: "[resource_shortdisplayname[Name]]"
		},{
			field: "UsersArePortalAdmins",
			title: "[resource_shortdisplayname[UsersArePortalAdmins]]",
			width: "50px",
			type: "boolean",
			template: `<span class="k-icon k-i-#: UsersArePortalAdmins ? 'check' : 'x' #"></span>`,
			editor: `<input type="checkbox" #: UsersArePortalAdmins ? 'checked' : '' #></input>`
		}];
		roleGrid.commands.push({
			name: "[resource_displayname[save]]",
			icon: 'k-i-save',
			text: "[resource_displayname[save]]"
		});
		roleGrid.commands.push({
			name: "[resource_displayname[destroy]]",
			icon: 'k-i-trash',
			text: "[resource_displayname[delete]]"
		});

		roleGrid.detailTemplate = $("script[name=roleDetails]", container).html();

		roleGrid.detailExpand = function (e) {
			SSORoleManagement.expandRole(e, app, roleGrid);
		};

		roleGrid.dataBound = function () {
			$("button[name=save]", roleGrid.gridElement).off("click").on("click", async (e) => await SSORoleManagement.save(e, roleGrid));
			$("button[name=destroy]", roleGrid.gridElement).off("click").on("click", async (e) => await SSORoleManagement.destroy(e, roleGrid));
		};

		await roleGrid.init();
		$("button[name=createRole]", roleGrid.gridElement).off("click").on("click", async (e) => await SSORoleManagement.createRole(e, app, roleGrid, tenant));

		await loadComponent($('[name=roleUserManagementComponent]', container), 'SSORoleUserManagement');
		await loadComponent($('[name=rolePrivManagementComponent]', container), 'SSORolePrivManagement');
	},

	save: async function (e, grid) {
		e.preventDefault();
		var role = grid.dataItem($(e.currentTarget).closest("tr"));
		await role.save().then(() => { 
			notification.success("[resource_displayname[RoleSaved]]"); 
		}).catch((err) => {
			error(err);
		});
	},

	destroy: async function (e, grid) {
		e.preventDefault();
		var row = $(e.currentTarget).closest("tr");
		var role = grid.dataItem(row);
		grid.dataSource().remove(role);
		await api.destroy("Security/SSORole(" + role.Id + ")").then(() => { 
			notification.success("[resource_displayname[roledeleted]]"); 
		}).catch((err) => {
			error(err);
		});
	},

	expandRole: async function (e, app, grid, container) {
		var role = grid.dataItem(e.masterRow);
		var container = $(e.detailRow);

		if (container.data("sso-role-initialised")) {
			return;
		}
		container.data("sso-role-initialised", true);

		var replaced = container.html().replaceAll('{ID}', Guid());
		container.html(replaced);

		await SSORoleUserManagement.init(app, $("[name=userGrid]", container), role);
		await SSORolePrivManagement.init(app, $("[name=privGrid]", container), role);
	},

	createRole: function (e, app, grid, tenant) {
        var newRole = {
            TenantId: tenant.Id,
            Name: "[resource_displayname[newrole]]",
            Privs: ""
        };
		var args = {
			fields: [{
				field: "Name",
				title: "[resource_displayname[name]]"
			}],
			title: "[resource_displayname[newRole]]",
			data: newRole,
			confirm: "<span class='k-icon k-i-plus'></span>[resource_displayname[confirm]]",
			close: "[resource_displayname[close]]"
		};
		var addRoleDialog = new EditorDialog(args);
		addRoleDialog.events.confirm = async function () {
			newRole = addRoleDialog.data;//Remove all the kendo observable properties.
			await api.add("Security/SSORole", newRole).then(() => {
                notification.success('[resource_displayname[RoleCreated]]');
			    grid.refresh();
			    addRoleDialog.events.close();
            }).catch((err) => error(err));
		};
		addRoleDialog.init();
	}
}
