    "Script": "SSORoleUserManagement = {
    init: async function (app, container, role) {
        app = app || session.app;
        container = container || $(".component[name=SSORoleUserManagement]");
        if(!role) { return; }
        api.addToMetaCache([{
            Name: "Security",
            Types: [
                [meta[Security/SSOUser]],
                [meta[Security/SSOUserRole]]
            ]
        }]);
        await SSORoleUserManagement.setupUserGrid(container, role);
    },

    setupUserGrid: async function(container, role) {
        var ds = await model.getDatasource({ endpoint: "Security/SSOUserRole", odataAppend: "?$filter=RoleId eq " + role.Id + "&$expand=User" });
        var usersGrid = new GridWidget(container, ds);
        usersGrid.commandWidth = 100;
        usersGrid.columns = [
            { field: "UserId", title: "[resource_displayname[userid]]" },
            { field: "User.Email", title: "[resource_displayname[email]]" }
        ];
        usersGrid.toolbar = `<div class="btn-group btn-group-sm">
            <button class="btn btn-primary" name="addUser">
                <span class="k-icon k-i-plus"></span>[resource_displayname[adduserbyid]]
            </button>
            <button class="btn btn-primary" name="addUsers">
                <span class="k-icon k-i-plus"></span>[resource_displayname[selectusers]]
            </button>
        </div>`;
        usersGrid.groupable = false;
        usersGrid.filterable = true;
        usersGrid.commands.push({ name: "delete", icon: "k-i-trash", text: "[resource_displayname[delete]]" });
        usersGrid.dataBound = function() { 
            $("[name=delete]", usersGrid.gridElement).off("click").on("click", async function(e) {
		        var item = usersGrid.dataItem($(e.currentTarget).closest("tr"));
                await SSORoleUserManagement.deleteUser(item, usersGrid);
            });
        };
        await usersGrid.init();
        $("[name=addUser]", usersGrid.gridElement).off("click").on("click", async (e) => await SSORoleUserManagement.addUser(e, role, usersGrid));
        $("[name=addUsers]", usersGrid.gridElement).off("click").on("click", async (e) => await SSORoleUserManagement.addUsers(e, usersGrid, role));
    },

	addUsers: async function(e, grid, role) {
        e.preventDefault();
        var userGrid = null;
        var userDialog = new Dialog({
            title: "[resource_displayname[selectusers]]",
            width: 800
        });
        userDialog.template = $("[name=selectusersdialog]").first().html();
        userDialog.events.select = async function(e) {
            e.preventDefault();
			var selected = userGrid.select();
            for(let i = 0; i < selected.length; i++) {
                var selectedUser = selected[i];
                if(!selectedUser) { continue; }
				await api.post("Security/SSOUserRole", {
                    RoleId: role.Id,
                    UserId: selectedUser.Id
                }).then(() => {
					grid.refresh();
				}).catch((e) => error(e));
			}
			userDialog.events.close();
        };
        userDialog.init(async () => {
            var userData = await model.getDatasource({
                endpoint: "Security/SSOUser",
                odataAppend: "?$filter=IsActive eq true",
                pageSize: 10
            });
            userGrid = new GridWidget($("[name=selectUsersGrid]", userDialog.element), userData);
			userGrid.filterable = true;
			userGrid.groupable = false;
            userGrid.pageable = true;
            userGrid.columns = [
                {selectable: true, width: 50},
                { field: "Id", title: "[resource_displayname[userid]]" },
                { field: "DisplayName", title: "[resource_displayname[displayname]]" },
                { field: "Email", title: "[resource_displayname[email]]" }
            ];
            userGrid.init();
        });
    },

    deleteUser: async function(roleUser, usersGrid) {
        await api.destroy("Security/SSOUserRole(RoleId=" + roleUser.RoleId + ",UserId='" + roleUser.UserId + "')").then(() => {
            notification.success("[resource_displayname[userdeleted]]");
            usersGrid.refresh();
        }).catch((err) => error(err));
    },

    addUser: async function (e, role, grid) {
        e.preventDefault();
        var model = kendo.observable({
            RoleId: role.Id,
            UserId: ""
        });
        var addUserDialog = new Dialog({
            title: "[resource_displayname[adduser]]",
            width: 500
        });
        addUserDialog.template = $("[name=addUserDialog]").html();
        addUserDialog.events.confirm = async function (e) {
            await api.add("Security/SSOUserRole", model).then(() => {
                notification.success("[resource_displayname[added]]");
                if (role.Users) { role.Users.push({ RoleId: role.Id, UserId:  model.UserId }); }
                addUserDialog.events.close();
                grid.refresh();
            }).catch((err) => error(err));
        };
        addUserDialog.init();
        kendo.bind(addUserDialog.element, model);
    }
}
