.btn:hover,.btn:focus-visible,.docs-nav-command:hover,.docs-nav-command:focus-visible,.public-card-action a:hover,.public-card-action a:focus-visible,.k-toolbar .k-button:hover,.k-toolbar .k-button:focus,.k-grid .k-command-cell .k-button:hover,.k-grid .k-command-cell .k-button:focus,.k-grid .k-grid-toolbar .k-button:hover,.k-grid .k-grid-toolbar .k-button:focus,.k-dialog .k-button:hover,.k-dialog .k-button:focus{border-color:var(--site-secondary)!important;background:var(--site-secondary)!important;color:var(--site-contrast)!important;box-shadow:none!important}
.btn:focus-visible,.docs-nav-command:focus-visible,.public-card-action a:focus-visible,.k-button:focus-visible{outline:2px solid var(--site-accent);outline-offset:2px}
.btn .k-icon,.btn i,.docs-nav-command-call,.docs-nav-command-arrow,.public-card-action a .k-icon,.k-toolbar .k-button .k-icon,.k-grid .k-command-cell .k-button .k-icon,.k-grid .k-grid-toolbar .k-button .k-icon,.k-dialog .k-button .k-icon{color:var(--site-accent)!important}
