.btn-sm,.k-button-sm{padding:.25rem .5rem!important;font-size:.875em}
.btn-lg{padding:.65rem 1rem!important;font-size:1.15em}
.btn:disabled,.btn.disabled,.k-button:disabled,.k-disabled{opacity:.55;cursor:not-allowed}
.btn-group>.btn,.k-button-group>.k-button{margin-left:-1px}
.btn-group>.btn:not(:first-child),.k-button-group>.k-button:not(:first-child){border-top-left-radius:0!important;border-bottom-left-radius:0!important}
.btn-group>.btn:not(:last-child),.k-button-group>.k-button:not(:last-child){border-top-right-radius:0!important;border-bottom-right-radius:0!important}
.navbar-toggler,.nav-link,.accordion-button,.k-pager .k-button{font-family:inherit}/* Semantic diagram blocks. */
.tri-nature-diagram::before,.tri-nature-diagram::after{display:block;align-self:stretch;color:var(--ccoder-semantic-blue);font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,"Liberation Mono",monospace;font-size:var(--ccoder-brace-size);font-weight:400;line-height:1;text-align:left}
