.worked-example-diagram{display:flex;flex-direction:column;align-items:center;width:100%;margin:0;padding:0}
.worked-example-diagram::before,.worked-example-diagram::after{display:block;align-self:stretch;color:var(--ccoder-semantic-blue);font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,"Liberation Mono",monospace;font-size:var(--ccoder-brace-size);font-weight:400;line-height:1;text-align:left}
.worked-example-diagram::before{content:"{";margin-bottom:var(--site-gap)}.worked-example-diagram::after{content:"}";margin-top:var(--site-gap)}
.worked-example-diagram figcaption{width:100%;margin:0 0 calc(var(--site-gap)*2);color:var(--site-primary);font-size:1.15rem;font-weight:700;text-align:center}
.worked-example-lane{position:relative;display:flex;flex-direction:column;align-items:center;box-sizing:border-box;width:min(100%,860px);padding:calc(var(--site-gap)*3) calc(var(--site-gap)*2) calc(var(--site-gap)*2);border:1px dashed rgba(14,111,174,.38);border-radius:var(--site-radius);background:rgba(255,255,255,.38)}
.worked-example-role{position:absolute;top:0;left:var(--site-gap);padding:.3rem .65rem;border-radius:999px;background:var(--site-primary);color:var(--site-contrast);font-weight:700;letter-spacing:.06em;text-transform:uppercase;transform:translateY(-50%)}
.worked-example-node{box-sizing:border-box;width:min(100%,680px);padding:calc(var(--site-gap)*2);border:1px solid rgba(14,111,174,.28);border-left:6px solid var(--site-primary);border-radius:var(--site-radius);background:var(--site-surface);box-shadow:var(--site-shadow)}
.worked-example-node>h3{margin-top:0}.worked-example-purpose .worked-example-node{border-left-color:var(--site-secondary)}.worked-example-dependency .worked-example-node{border-left-color:var(--site-accent)}
.worked-example-call{position:relative;flex:0 0 64px;width:3px;min-height:64px;background:linear-gradient(var(--site-secondary),var(--site-primary))}
.worked-example-call::after{content:"";position:absolute;bottom:-1px;left:50%;width:10px;height:10px;border-right:3px solid var(--site-primary);border-bottom:3px solid var(--site-primary);transform:translateX(-50%) rotate(45deg)}
.worked-example-call>span{position:absolute;top:50%;left:14px;padding:.1rem .35rem;background:var(--site-background);color:var(--site-secondary);font-size:.8em;white-space:nowrap;transform:translateY(-50%)}
.worked-example-purpose>.worked-example-call{flex-basis:52px;min-height:52px}
