(function(){
  function applyImageSemantics(){
    document.querySelectorAll('.docs-content img:not([data-ccoder-semantic-image])').forEach(function(image){
      image.setAttribute('data-ccoder-semantic-image','true');
      var parent=image.parentElement;
      if(parent&&parent.tagName==='P'&&(parent.textContent||'').trim()==='')parent.classList.add('semantic-image-host');
      var block=document.createElement('span');
      block.className='semantic-image-block';
      image.parentNode.insertBefore(block,image);
      block.appendChild(image);
    });
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',applyImageSemantics);
  else applyImageSemantics();
})();
</script>




